		        p.graphics.beginFill(color).drawCircle(0, 0, size);
		        p.x = x; p.y = y;
		        p.alpha = 0.7 + Math.random() * 0.3;
		        p.scaleX = p.scaleY = 0.8 + Math.random() * 1.2;
		
